int apples = 17;
int bags = 5;
int per_bag = apples / bags;     // 3
int left_over = apples % bags;   // 2

int age = 19;
char grade = 'A';
printf("age %d, grade %c\n", age, grade);   // age 19, grade A
printf("%d in hex is %x\n", 255, 255);      // 255 in hex is ff

int n;
printf("How many? ");
scanf("%d", &n);                 // &n is the address of n

void try_to_reset(int x) {
    x = 0;                       // changes the copy only
}

int main(void) {
    int score = 12;
    try_to_reset(score);
    printf("%d\n", score);       // still 12
    return 0;
}

void divmod(int a, int b, int *q, int *r) {
    *q = a / b;                  // write into the caller's quot
    *r = a % b;                  // write into the caller's rem
}

int main(void) {
    int quot, rem;
    divmod(38, 7, &quot, &rem);
    printf("38 = 7 * %d + %d\n", quot, rem);   // 38 = 7 * 5 + 3
    return 0;
}

int i = 1;
while (i <= 3) {                 // test first: may run zero times
    printf("%d ", i);            // prints 1 2 3
    i++;
}

int j = 10;
do {                             // body first: runs at least once
    printf("%d ", j);            // prints 10, once
    j++;
} while (j <= 3);

for (int k = 1; k <= 3; k++) {   // the same loop as the while above
    printf("%d ", k);
}

int marks[6] = {70, 85, 62, 91, 78, 64};
int total = 0;

for (int i = 0; i < 6; i++) {    // by index
    total += marks[i];
}

total = 0;
int *p = marks;                  // p = &marks[0]
int *end = marks + 6;            // one past the last element
while (p < end) {                // by pointer
    total += *p;
    p++;                         // moves 4 bytes: one int
}
printf("total = %d\n", total);   // total = 450

#include <stdio.h>

int average3(int a, int b, int c) {
    return (a + b + c) / 3;
}

int main(void) {
    int s1 = 10, s2 = 20, s3 = 25;
    printf("average of %d, %d and %d is %d\n", s1, s2, s3, average3(s1, s2, s3));
    return 0;
}
